public class FitnessFunction_decode_TriageGen1Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testDecode_BoundariesNull() {
        CMAESOptimizer.FitnessFunction fitnessFunction = new CMAESOptimizer.FitnessFunction();
        // Since boundaries is null by default via constructor
        double[] x = {1.0, 2.0, 3.0};
        double[] result = fitnessFunction.decode(x);

        // If boundaries is null, it should return the exact same array reference
        assertSame(x, result);
    }

    @Test
    public void testDecode_WithBoundaries() {
        CMAESOptimizer.FitnessFunction fitnessFunction = new CMAESOptimizer.FitnessFunction();

        // Manually inject boundaries using Reflection because it's likely a private field
        // boundaries[0] is lower bound, boundaries[1] is upper bound
        double[][] boundaries = {
            {0.0, 10.0, -5.0}, // Lower bounds
            {1.0, 20.0, 5.0}   // Upper bounds
        };
        ReflectionTestUtils.setField(fitnessFunction, "boundaries", boundaries);

        double[] x = {0.5, 0.5, 0.5};
        // Calculation:
        // i=0: (1.0 - 0.0) * 0.5 + 0.0 = 0.5
        // i=1: (20.0 - 10.0) * 0.5 + 10.0 = 15.0
        // i=2: (5.0 - (-5.0)) * 0.5 + (-5.0) = 10.0 * 0.5 - 5.0 = 0.0

        double[] expected = {0.5, 15.0, 0.0};
        double[] result = fitnessFunction.decode(x);

        assertArrayEquals(expected, result, DELTA);
    }

    @Test
    public void testDecode_ZeroRangeBoundaries() {
        CMAESOptimizer.FitnessFunction fitnessFunction = new CMAESOptimizer.FitnessFunction();

        double[][] boundaries = {
            {5.0, 5.0},
            {5.0, 5.0}
        };
        ReflectionTestUtils.setField(fitnessFunction, "boundaries", boundaries);

        double[] x = {1.0, 100.0};
        // Calculation:
        // i=0: (5-5)*1 + 5 = 5
        // i=1: (5-5)*100 + 5 = 5

        double[] expected = {5.0, 5.0};
        double[] result = fitnessFunction.decode(x);

        assertArrayEquals(expected, result, DELTA);
    }

    @Test
    public void testDecode_NegativeValues() {
        CMAESOptimizer.FitnessFunction fitnessFunction = new CMAESOptimizer.FitnessFunction();

        double[][] boundaries = {
            {-10.0},
            {-2.0}
        };
        ReflectionTestUtils.setField(fitnessFunction, "boundaries", boundaries);

        double[] x = {1.0};
        // diff = -2.0 - (-10.0) = 8.0
        // res = 8.0 * 1.0 + (-10.0) = -2.0

        double[] expected = {-2.0};
        double[] result = fitnessFunction.decode(x);

        assertArrayEquals(expected, result, DELTA);
    }
}
